18	package org.keycloak.jose.jws;
19	
20	import java.io.IOException;
21	import java.nio.charset.StandardCharsets;
22	import java.security.PrivateKey;
23	import java.security.cert.CertificateEncodingException;
24	import java.security.cert.X509Certificate;
25	import java.util.Base64;
26	import java.util.List;
27	import java.util.stream.Collectors;
28	import javax.crypto.SecretKey;
29	
30	import org.keycloak.common.util.Base64Url;
31	import org.keycloak.crypto.SignatureSignerContext;
32	import org.keycloak.jose.jwk.JWK;
33	import org.keycloak.jose.jws.crypto.HMACProvider;
34	import org.keycloak.jose.jws.crypto.RSAProvider;
35	import org.keycloak.json.KeycloakJsonMapperFactory;
36	
37	
38	/**
39	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
40	 * @version $Revision: 1 $
41	 */
42	public class JWSBuilder {
43	    protected String type;
44	    protected String kid;
45	    protected String x5t;
46	    protected JWK jwk;
47	    protected List<String> x5c;
48	    protected String contentType;
49	    protected byte[] contentBytes;
50	
51	    public JWSBuilder type(String type) {
52	        this.type = type;
53	        return this;
54	    }
55	
56	    public JWSBuilder kid(String kid) {
57	        this.kid = kid;
58	        return this;
59	    }
60	
61	    public JWSBuilder x5t(String x5t) {
62	        this.x5t = x5t;
63	        return this;
64	    }
65	
66	    public JWSBuilder jwk(JWK jwk) {
67	        this.jwk = jwk;
68	        return this;
69	    }
70	
71	    public JWSBuilder x5c(List<X509Certificate> x5c) {
72	        this.x5c = x5c.stream()
73	                .map(x509Certificate -> {
74	                    try {
75	                        return Base64.getEncoder().encodeToString(x509Certificate.getEncoded());
76	                    } catch (CertificateEncodingException e) {
77	                        throw new RuntimeException(e);
78	                    }
79	                })
80	                .collect(Collectors.toList());
81	        return this;
82	    }
83	
84	    public JWSBuilder contentType(String type) {
85	        this.contentType = type;
86	        return this;
87	    }
88	
89	    public JWSBuilder header(JWSHeader header) {
90	        this.type = header.getType();
91	        this.kid = header.getKeyId();
92	        this.jwk = header.getKey();
93	        this.x5c = header.getX5c();
94	        this.contentType = header.getContentType();
95	        return this;
96	    }
97	
98	    public EncodingBuilder content(byte[] bytes) {
99	        this.contentBytes = bytes;
100	        return new EncodingBuilder();
101	    }
102	
103	    public EncodingBuilder jsonContent(Object object) {
104	        try {
105	            this.contentBytes = KeycloakJsonMapperFactory.mapper().writeValueAsBytes(object);
106	        } catch (IOException e) {
107	            throw new RuntimeException(e);
108	        }
109	        return new EncodingBuilder();
110	    }
111	
112	
113	    protected String encodeHeader(String sigAlgName) {
114	        StringBuilder builder = new StringBuilder("{");
115	
116	        if (org.keycloak.crypto.Algorithm.Ed25519.equals(sigAlgName) || org.keycloak.crypto.Algorithm.Ed448.equals(sigAlgName)) {
117	            builder.append("\"alg\":\"").append(org.keycloak.crypto.Algorithm.EdDSA).append("\"");
118	            builder.append(",\"crv\":\"").append(sigAlgName).append("\"");
119	        } else {
120	            builder.append("\"alg\":\"").append(sigAlgName).append("\"");
121	        }
122	
123	        if (type != null) builder.append(",\"typ\" : \"").append(type).append("\"");
124	        if (kid != null) builder.append(",\"kid\" : \"").append(kid).append("\"");
125	        if (x5t != null) builder.append(",\"x5t\" : \"").append(x5t).append("\"");
126	        if (x5c != null && !x5c.isEmpty()) {
127	            builder.append(",\"x5c\" : [");
128	            for (int i = 0; i < x5c.size(); i++) {
129	                String certificate = x5c.get(i);
130	                if (i > 0) {
131	                    builder.append(",");
132	                }
133	                builder.append("\"").append(certificate).append("\"");
134	            }
135	            builder.append("]");
136	        }
137	        if (jwk != null) {
138	            try {
139	                builder.append(",\"jwk\" : ").append(KeycloakJsonMapperFactory.mapper().writeValueAsString(jwk));
140	            } catch (IOException e) {
141	                throw new RuntimeException(e);
142	            }
143	        }
144	        if (contentType != null) builder.append(",\"cty\":\"").append(contentType).append("\"");
145	        builder.append("}");
146	        return Base64Url.encode(builder.toString().getBytes(StandardCharsets.UTF_8));
147	    }
148	
149	    protected String encodeAll(StringBuilder encoding, byte[] signature) {
150	        encoding.append('.');
151	        if (signature != null) {
152	            encoding.append(Base64Url.encode(signature));
153	        }
154	        return encoding.toString();
155	    }
156	
157	    protected void encode(Algorithm alg, byte[] data, StringBuilder encoding) {
158	        encode(alg.name(), data, encoding);
159	    }
160	
161	    protected void encode(String sigAlgName, byte[] data, StringBuilder encoding) {
162	        encoding.append(encodeHeader(sigAlgName));
163	        encoding.append('.');
164	        encoding.append(Base64Url.encode(data));
165	    }
166	
167	    protected byte[] marshalContent() {
168	        return contentBytes;
169	    }
170	
171	    public class EncodingBuilder {
172	
173	        public String sign(SignatureSignerContext signer) {
174	            kid = signer.getKid();
175	
176	            StringBuilder buffer = new StringBuilder();
177	            byte[] data = marshalContent();
178	            encode(signer.getAlgorithm(), data, buffer);
179	            byte[] signature = null;
180	            try {
181	                signature = signer.sign(buffer.toString().getBytes(StandardCharsets.UTF_8));
182	            } catch (Exception e) {
183	                throw new RuntimeException(e);
184	            }
185	            return encodeAll(buffer, signature);
186	        }
187	
188	        public String none() {
189	            StringBuilder buffer = new StringBuilder();
190	            byte[] data = marshalContent();
191	            encode(Algorithm.none, data, buffer);
192	            return encodeAll(buffer, null);
193	        }
194	
195	        @Deprecated
196	        public String sign(Algorithm algorithm, PrivateKey privateKey) {
197	            StringBuilder buffer = new StringBuilder();
198	            byte[] data = marshalContent();
199	            encode(algorithm, data, buffer);
200	            byte[] signature = RSAProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), algorithm, privateKey);
201	            return encodeAll(buffer, signature);
202	        }
203	
204	        @Deprecated
205	        public String rsa256(PrivateKey privateKey) {
206	            return sign(Algorithm.RS256, privateKey);
207	        }
208	
209	        @Deprecated
210	        public String rsa384(PrivateKey privateKey) {
211	            return sign(Algorithm.RS384, privateKey);
212	        }
213	
214	        @Deprecated
215	        public String rsa512(PrivateKey privateKey) {
216	            return sign(Algorithm.RS512, privateKey);
217	        }
218	
219	        @Deprecated
220	        public String hmac256(byte[] sharedSecret) {
221	            StringBuilder buffer = new StringBuilder();
222	            byte[] data = marshalContent();
223	            encode(Algorithm.HS256, data, buffer);
224	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS256, sharedSecret);
225	            return encodeAll(buffer, signature);
226	        }
227	
228	        @Deprecated
229	        public String hmac384(byte[] sharedSecret) {
230	            StringBuilder buffer = new StringBuilder();
231	            byte[] data = marshalContent();
232	            encode(Algorithm.HS384, data, buffer);
233	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS384, sharedSecret);
234	            return encodeAll(buffer, signature);
235	        }
236	
237	        @Deprecated
238	        public String hmac512(byte[] sharedSecret) {
239	            StringBuilder buffer = new StringBuilder();
240	            byte[] data = marshalContent();
241	            encode(Algorithm.HS512, data, buffer);
242	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS512, sharedSecret);
243	            return encodeAll(buffer, signature);
244	        }
245	
246	        @Deprecated
247	        public String hmac256(SecretKey sharedSecret) {
248	            StringBuilder buffer = new StringBuilder();
249	            byte[] data = marshalContent();
250	            encode(Algorithm.HS256, data, buffer);
251	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS256, sharedSecret);
252	            return encodeAll(buffer, signature);
253	        }
254	
255	        @Deprecated
256	        public String hmac384(SecretKey sharedSecret) {
257	            StringBuilder buffer = new StringBuilder();
258	            byte[] data = marshalContent();
259	            encode(Algorithm.HS384, data, buffer);
260	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS384, sharedSecret);
261	            return encodeAll(buffer, signature);
262	        }
263	
264	        @Deprecated
265	        public String hmac512(SecretKey sharedSecret) {
266	            StringBuilder buffer = new StringBuilder();
267	            byte[] data = marshalContent();
268	            encode(Algorithm.HS512, data, buffer);
269	            byte[] signature = HMACProvider.sign(buffer.toString().getBytes(StandardCharsets.UTF_8), Algorithm.HS512, sharedSecret);
270	            return encodeAll(buffer, signature);
271	        }
272	    }
273	}
