18	package org.keycloak.jose.jws;
19	
20	import java.io.IOException;
21	import java.nio.charset.StandardCharsets;
22	
23	import org.keycloak.common.util.Base64Url;
24	import org.keycloak.jose.JOSE;
25	import org.keycloak.json.KeycloakJsonMapperFactory;
26	
27	/**
28	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
29	 * @version $Revision: 1 $
30	 */
31	public class JWSInput implements JOSE {
32	    String wireString;
33	    String encodedHeader;
34	    String encodedContent;
35	    String encodedSignature;
36	    String encodedSignatureInput;
37	    JWSHeader header;
38	    byte[] content;
39	    byte[] signature;
40	
41	
42	    public JWSInput(String wire) throws JWSInputException {
43	        try {
44	            this.wireString = wire;
45	            String[] parts = wire.split("\\.");
46	            if (parts.length < 2 || parts.length > 3) throw new IllegalArgumentException("Parsing error");
47	            encodedHeader = parts[0];
48	            encodedContent = parts[1];
49	            encodedSignatureInput = encodedHeader + '.' + encodedContent;
50	            content = Base64Url.decode(encodedContent);
51	            if (parts.length > 2) {
52	                encodedSignature = parts[2];
53	                signature = Base64Url.decode(encodedSignature);
54	
55	            }
56	            byte[] headerBytes = Base64Url.decode(encodedHeader);
57	            header = KeycloakJsonMapperFactory.mapper().readValue(headerBytes, JWSHeader.class);
58	        } catch (Throwable t) {
59	            throw new JWSInputException(t);
60	        }
61	    }
62	
63	    public String getWireString() {
64	        return wireString;
65	    }
66	
67	    public String getEncodedHeader() {
68	        return encodedHeader;
69	    }
70	
71	    public String getEncodedContent() {
72	        return encodedContent;
73	    }
74	
75	    public String getEncodedSignature() {
76	        return encodedSignature;
77	    }
78	    public String getEncodedSignatureInput() {
79	        return encodedSignatureInput;
80	    }
81	
82	    public JWSHeader getHeader() {
83	        return header;
84	    }
85	
86	    public byte[] getContent() {
87	        return content;
88	    }
89	
90	    public byte[] getSignature() {
91	        return signature;
92	    }
93	
94	    public <T> T readJsonContent(Class<T> type) throws JWSInputException {
95	        try {
96	            return KeycloakJsonMapperFactory.mapper().readValue(content, type);
97	        } catch (IOException e) {
98	            throw new JWSInputException(e);
99	        }
100	    }
101	
102	    public String readContentAsString() {
103	        return new String(content, StandardCharsets.UTF_8);
104	    }
105	}
