18	package org.keycloak.jose.jwk;
19	
20	import java.math.BigInteger;
21	import java.security.KeyFactory;
22	import java.security.PublicKey;
23	import java.security.spec.ECParameterSpec;
24	import java.security.spec.ECPoint;
25	import java.security.spec.ECPublicKeySpec;
26	import java.security.spec.RSAPublicKeySpec;
27	
28	import org.keycloak.common.crypto.CryptoIntegration;
29	import org.keycloak.common.util.Base64Url;
30	import org.keycloak.crypto.KeyType;
31	import org.keycloak.json.KeycloakJsonMapperFactory;
32	import org.keycloak.json.RawJsonValue;
33	
34	/**
35	 * @author <a href="mailto:sthorger@redhat.com">Stian Thorgersen</a>
36	 */
37	public class JWKParser {
38	
39	    protected JWK jwk;
40	
41	    private JWKParser() {
42	    }
43	
44	    public static JWKParser create() {
45	        return new JWKParser();
46	    }
47	
48	    public JWKParser(JWK jwk) {
49	        this.jwk = jwk;
50	    }
51	
52	    public static JWKParser create(JWK jwk) {
53	        return new JWKParser(jwk);
54	    }
55	
56	    public JWKParser parse(String jwk) {
57	        try {
58	            this.jwk = KeycloakJsonMapperFactory.mapper().readValue(jwk, JWK.class);
59	            return this;
60	        } catch (Exception e) {
61	            throw new RuntimeException(e);
62	        }
63	    }
64	
65	    public JWK getJwk() {
66	        return jwk;
67	    }
68	
69	    public PublicKey toPublicKey() {
70	        if (jwk == null) {
71	            throw new IllegalStateException("Not possible to convert to the publicKey. The jwk is not set");
72	        }
73	        String keyType = jwk.getKeyType();
74	
75	        // subtypes may store properties differently while representing the same JWK, serializing it to nodes
76	        // makes sure there is no difference when creating the keys
77	        RawJsonValue normalizedJwk = KeycloakJsonMapperFactory.mapper().convertValue(jwk, RawJsonValue.class);
78	        if (KeyType.RSA.equals(keyType)) {
79	            return createRSAPublicKey(normalizedJwk);
80	        } else if (KeyType.EC.equals(keyType)) {
81	            return createECPublicKey(normalizedJwk);
82	        } else if (KeyType.OKP.equals(keyType)) {
83	            return JWKBuilder.EdEC_UTILS.createOKPPublicKey(jwk);
84	        } else if (KeyType.AKP.equals(keyType)) {
85	            return createAPKPublicKey(normalizedJwk);
86	        } else {
87	            throw new RuntimeException("Unsupported keyType " + keyType);
88	        }
89	    }
90	
91	    private static PublicKey createECPublicKey(RawJsonValue jwk) {
92	
93	
94	        /* Try retrieving the necessary fields */
95	        String crv = jwk.path(ECPublicJWK.CRV).asText(null);
96	        String xStr = jwk.get(ECPublicJWK.X).asText(null);
97	        String yStr = jwk.get(ECPublicJWK.Y).asText(null);
98	
99	        /* Check if the retrieving of necessary fields success */
100	        if (crv == null || xStr == null || yStr == null) {
101	            throw new RuntimeException("Fail to retrieve ECPublicJWK.CRV, ECPublicJWK.X or ECPublicJWK.Y field.");
102	        }
103	
104	        BigInteger x = new BigInteger(1, Base64Url.decode(xStr));
105	        BigInteger y = new BigInteger(1, Base64Url.decode(yStr));
106	
107	        String name;
108	        switch (crv) {
109	            case "P-256" :
110	                name = "secp256r1";
111	                break;
112	            case "P-384" :
113	                name = "secp384r1";
114	                break;
115	            case "P-521" :
116	                name = "secp521r1";
117	                break;
118	            default :
119	                throw new RuntimeException("Unsupported curve");
120	        }
121	
122	        try {
123	
124	            ECPoint point = new ECPoint(x, y);
125	            ECParameterSpec params = CryptoIntegration.getProvider().createECParams(name);
126	            ECPublicKeySpec pubKeySpec = new ECPublicKeySpec(point, params);
127	
128	            KeyFactory kf = CryptoIntegration.getProvider().getKeyFactory("ECDSA");
129	            return kf.generatePublic(pubKeySpec);
130	        } catch (Exception e) {
131	            throw new RuntimeException(e);
132	        }
133	    }
134	
135	    private static PublicKey createRSAPublicKey(RawJsonValue jwk) {
136	        BigInteger modulus = new BigInteger(1, Base64Url.decode(jwk.path(RSAPublicJWK.MODULUS).asText(null)));
137	        BigInteger publicExponent = new BigInteger(1, Base64Url.decode(jwk.path(RSAPublicJWK.PUBLIC_EXPONENT).asText(null)));
138	
139	        try {
140	            KeyFactory kf = KeyFactory.getInstance("RSA");
141	            return kf.generatePublic(new RSAPublicKeySpec(modulus, publicExponent));
142	        } catch (Exception e) {
143	            throw new RuntimeException(e);
144	        }
145	    }
146	
147	    private static PublicKey createAPKPublicKey(RawJsonValue jwk) {
148	        String algorithm = jwk.path(JWK.ALGORITHM).asText();
149	        String publicKey = jwk.path(AKPPublicJWK.PUB).asText();
150	        return AKPUtils.fromEncodedPub(publicKey, algorithm);
151	    }
152	
153	    public boolean isKeyTypeSupported(String keyType) {
154	        return (RSAPublicJWK.RSA.equals(keyType) || ECPublicJWK.EC.equals(keyType)
155	                || (JWKBuilder.EdEC_UTILS.isEdECSupported() && OKPPublicJWK.OKP.equals(keyType)))
156	                || KeyType.AKP.equals(keyType);
157	    }
158	}
