18	package org.keycloak.jose.jwk;
19	
20	import java.security.NoSuchAlgorithmException;
21	
22	import org.keycloak.common.util.PemUtils;
23	
24	import com.fasterxml.jackson.annotation.JsonIgnore;
25	import com.fasterxml.jackson.annotation.JsonProperty;
26	
27	/**
28	 * @author <a href="mailto:sthorger@redhat.com">Stian Thorgersen</a>
29	 */
30	public class RSAPublicJWK extends JWK {
31	
32	    public static final String RSA = "RSA";
33	    public static final String RS256 = "RS256";
34	
35	    public static final String MODULUS = "n";
36	    public static final String PUBLIC_EXPONENT = "e";
37	
38	    @JsonProperty(MODULUS)
39	    private String modulus;
40	
41	    @JsonProperty("e")
42	    private String publicExponent;
43	
44	    @JsonProperty("x5c")
45	    private String[] x509CertificateChain;
46	
47	    private String sha1x509Thumbprint;
48	
49	    private String sha256x509Thumbprint;
50	
51	    public String getModulus() {
52	        return modulus;
53	    }
54	
55	    public void setModulus(String modulus) {
56	        this.modulus = modulus;
57	    }
58	
59	    public String getPublicExponent() {
60	        return publicExponent;
61	    }
62	
63	    public void setPublicExponent(String publicExponent) {
64	        this.publicExponent = publicExponent;
65	    }
66	    
67	    public String[] getX509CertificateChain() {
68	        return x509CertificateChain;
69	    }
70	
71	    public void setX509CertificateChain(String[] x509CertificateChain) {
72	        this.x509CertificateChain = x509CertificateChain;
73	        if (x509CertificateChain != null && x509CertificateChain.length > 0) {
74	            try {
75	                sha1x509Thumbprint = PemUtils.generateThumbprint(x509CertificateChain, "SHA-1");
76	                sha256x509Thumbprint = PemUtils.generateThumbprint(x509CertificateChain, "SHA-256");
77	            } catch (NoSuchAlgorithmException e) {
78	                throw new RuntimeException(e);
79	            }
80	        }
81	    }
