88	    @JsonProperty("x5t#S256")
89	    public String getSha256x509Thumbprint() {
90	        return sha256x509Thumbprint;
91	    }
92	
93	    @JsonIgnore
94	    @Override
95	    public <T> T getOtherClaim(String claimName, Class<T> claimType) {
96	        Object claim = null;
97	        switch (claimName) {
98	            case MODULUS:
99	                claim = getModulus();
100	                break;
101	            case PUBLIC_EXPONENT:
102	                claim = getPublicExponent();
103	                break;
