1	package org.keycloak.common.util;
2	
3	import java.net.URI;
4	import java.util.LinkedHashMap;
5	import java.util.Map;
6	import java.util.Objects;
7	import java.util.regex.Matcher;
8	import java.util.regex.Pattern;
9	
10	/**
11	 * Utilities to serialize objects to string. Type safety is not guaranteed here and is responsibility of the caller.
12	 * @author hmlnarik
13	 */
14	public class StringSerialization {
15	
16	    private enum DeSerializerFunction {
17	        OBJECT {
18	            @Override public String serialize(Object o)   { return o.toString(); }
19	            @Override public Object deserialize(String s) { return s; }
20	        },
21	        URI {
22	            @Override public String serialize(Object o)   { return o.toString(); }
23	            @Override public Object deserialize(String s) { return java.net.URI.create(s); }
24	        },
25	        ;
26	
27	        /** Serialize value which is guaranteed to be non-null */
28	        public abstract String serialize(Object o);
29	        public abstract Object deserialize(String s);
30	    }
31	
32	    private static final Map<Class<?>, DeSerializerFunction> WELL_KNOWN_DESERIALIZERS = new LinkedHashMap<>();
33	    private static final String SEPARATOR = ";";
34	    private static final Pattern ESCAPE_PATTERN = Pattern.compile(SEPARATOR);
35	    private static final Pattern UNESCAPE_PATTERN = Pattern.compile(SEPARATOR + SEPARATOR);
36	    private static final Pattern VALUE_PATTERN = Pattern.compile("([NV])" +
37	      "(" +
38	        "(?:[^" + SEPARATOR + "]|" + SEPARATOR + SEPARATOR + ")*?" +
39	      ")($|" + SEPARATOR + "(?!" + SEPARATOR + "))",
40	      Pattern.DOTALL
41	    );
42	
43	    static {
44	        WELL_KNOWN_DESERIALIZERS.put(URI.class, DeSerializerFunction.URI);
45	        WELL_KNOWN_DESERIALIZERS.put(String.class, DeSerializerFunction.OBJECT);
46	    }
47	
48	    /**
49	     * Serialize given objects as strings separated by {@link #SEPARATOR} according to the {@link #WELL_KNOWN_SERIALIZERS}.
50	     * @param toSerialize
51	     * @return
52	     */
53	    public static String serialize(Object... toSerialize) {
54	        StringBuilder sb = new StringBuilder();
55	
56	        for (int i = 0; i < toSerialize.length; i ++) {
57	            Object o = toSerialize[i];
58	            String stringO = getStringFrom(o);
59	            String escapedStringO = ESCAPE_PATTERN.matcher(stringO).replaceAll(SEPARATOR + SEPARATOR);
60	            sb.append(escapedStringO);
61	
62	            if (i < toSerialize.length - 1) {
63	                sb.append(SEPARATOR);
64	            }
65	        }
66	
67	        return sb.toString();
68	    }
69	
70	    public static Deserializer deserialize(String what) {
71	        return new Deserializer(what);
72	    }
73	
74	    private static String getStringFrom(Object o) {
75	        if (o == null) {
76	            return "N";
77	        }
78	
79	        Class<?> c = o.getClass();
80	        DeSerializerFunction f = WELL_KNOWN_DESERIALIZERS.get(c);
81	        return "V" + (f == null ? o : f.serialize(o));
82	    }
83	
84	    private static <T> T getObjectFrom(String escapedString, Class<T> clazz) {
85	        DeSerializerFunction f = WELL_KNOWN_DESERIALIZERS.get(clazz);
86	        Object res = f == null ? escapedString : f.deserialize(escapedString);
87	        return clazz.cast(res);
88	    }
89	
90	    public static class Deserializer {
91	
92	        private final Matcher valueMatcher;
93	
94	        public Deserializer(String what) {
95	            this.valueMatcher = VALUE_PATTERN.matcher(what);
96	        }
97	
98	        public <T> T next(Class<T> clazz) {
99	            if (! this.valueMatcher.find()) {
100	                return null;
101	            }
102	            String valueOrNull = this.valueMatcher.group(1);
103	            if (valueOrNull == null || Objects.equals(valueOrNull, "N")) {
104	                return null;
105	            }
106	            String escapedStringO = this.valueMatcher.group(2);
107	            String unescapedStringO = UNESCAPE_PATTERN.matcher(escapedStringO).replaceAll(SEPARATOR);
108	            return getObjectFrom(unescapedStringO, clazz);
109	        }
110	    }
111	}
