22	/**
23	 * @author <a href="mailto:sthorger@redhat.com">Stian Thorgersen</a>
24	 */
25	public class Time {
26	
27	    private static volatile int offset;
28	
29	    /**
30	     * Returns current time in seconds adjusted by adding {@link #offset} seconds.
31	     * @return see description
32	     * @deprecated Use {@link #currentTimeSeconds()} to avoid integer overflow beyond year 2038.
33	     */
34	    @Deprecated
35	    public static int currentTime() {
36	        return ((int) (System.currentTimeMillis() / 1000)) + offset;
37	    }
38	
39	    /**
40	     * Returns current time in seconds adjusted by adding {@link #offset} seconds.
41	     * Unlike {@link #currentTime()}, this method returns a {@code long} to avoid integer overflow beyond year 2038.
42	     * @return see description
43	     */
44	    public static long currentTimeSeconds() {
45	        return (System.currentTimeMillis() / 1000) + offset;
46	    }
47	
48	    /**
49	     * Returns current time in milliseconds adjusted by adding {@link #offset} seconds.
50	     * @return see description
51	     */
52	    public static long currentTimeMillis() {
53	        return System.currentTimeMillis() + (offset * 1000L);
54	    }
55	
56	    /**
57	     * Returns {@link Date} object, its value set to time
58	     * @param time Time in milliseconds since the epoch
59	     * @return see description
60	     */
61	    public static Date toDate(int time) {
62	        return new Date(time * 1000L);
63	    }
64	
65	    /**
66	     * Returns {@link Date} object, its value set to time
67	     * @param time Time in milliseconds since the epoch
68	     * @return see description
69	     */
70	    public static Date toDate(long time) {
71	        return new Date(time);
72	    }
73	
74	    /**
75	     * Returns time in milliseconds for a time in seconds. No adjustment is made to the parameter.
76	     * @param time Time in seconds since the epoch
77	     * @return Time in milliseconds
78	     */
79	    public static long toMillis(long time) {
80	        return time * 1000L;
81	    }
82	
83	    /**
84	     * @return Time offset in seconds that will be added to {@link #currentTime()} and {@link #currentTimeMillis()}.
85	     */
86	    public static int getOffset() {
87	        return offset;
88	    }
89	
90	    /**
91	     * Sets time offset in seconds that will be added to {@link #currentTime()} and {@link #currentTimeMillis()}.
92	     * @param offset Offset (in seconds)
93	     */
94	    public static void setOffset(int offset) {
95	        Time.offset = offset;
96	    }
97	
98	}
