34	/**
35	 * Utility class to handle simple JSON serializable for Keycloak.
36	 *
37	 * @author <a href="mailto:bill@burkecentral.com">Bill Burke</a>
38	 * @version $Revision: 1 $
39	 */
40	public class JsonSerialization {
41	    public static final ObjectMapper mapper = createObjectMapperWithDefaults();
42	    public static final ObjectMapper prettyMapper = createPrettyObjectMapperWithDefaults();
43	
44	    public static ObjectMapper createObjectMapperWithDefaults() {
45	        ObjectMapper mapper = new ObjectMapper();
46	        mapper.registerModule(new Jdk8Module());
47	        mapper.registerModule(new JavaTimeModule());
48	        mapper.configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false);
49	        mapper.setDefaultPropertyInclusion(JsonInclude.Include.NON_NULL);
50	        return mapper;
51	    }
52	
53	    public static ObjectMapper createPrettyObjectMapperWithDefaults() {
54	        ObjectMapper prettyMapper = new ObjectMapper();
55	        prettyMapper.configure(SerializationFeature.FAIL_ON_EMPTY_BEANS, false);
56	        prettyMapper.enable(SerializationFeature.INDENT_OUTPUT);
57	        prettyMapper.setDefaultPropertyInclusion(JsonInclude.Include.NON_NULL);
58	        return prettyMapper;
59	    }
60	
61	    public static String valueAsString(Object obj) {
62	        try {
63	            return mapper.writeValueAsString(obj);
64	        } catch (IOException e) {
65	            throw new IllegalArgumentException(e);
66	        }
67	    }
68	
69	    public static String valueAsPrettyString(Object obj) {
70	        try {
71	            return prettyMapper.writeValueAsString(obj);
72	        } catch (IOException e) {
73	            throw new IllegalArgumentException(e);
74	        }
75	    }
76	
77	    public static <T> T valueFromString(String string, Class<T> type) {
78	        try {
79	            return mapper.readValue(string, type);
80	        } catch (IOException e) {
81	            throw new IllegalArgumentException(e);
82	        }
83	    }
84	
85	    public static void writeValueToStream(OutputStream os, Object obj) throws IOException {
86	        mapper.writeValue(os, obj);
87	    }
88	
89	    public static void writeValuePrettyToStream(OutputStream os, Object obj) throws IOException {
90	        prettyMapper.writeValue(os, obj);
91	    }
92	
93	    public static String writeValueAsPrettyString(Object obj) throws IOException {
94	        return prettyMapper.writeValueAsString(obj);
95	    }
96	    public static String writeValueAsString(Object obj) throws IOException {
97	        return mapper.writeValueAsString(obj);
98	    }
99	
100	    public static byte[] writeValueAsBytes(Object obj) throws IOException {
101	        return mapper.writeValueAsBytes(obj);
102	    }
103	
104	    public static JsonNode writeValueAsNode(Object obj) {
105	        return mapper.valueToTree(obj);
106	    }
107	
108	    public static <T> T readValue(byte[] bytes, Class<T> type) throws IOException {
109	        return mapper.readValue(bytes, type);
110	    }
111	
112	    public static <T> T readValue(String bytes, Class<T> type) throws IOException {
113	        return mapper.readValue(bytes, type);
114	    }
115	
116	    public static <T> T readValue(InputStream bytes, Class<T> type) throws IOException {
117	        return mapper.readValue(bytes, type);
118	    }
119	
120	    public static <T> T readValue(byte[] bytes, TypeReference<T> type) throws IOException {
121	        return mapper.readValue(bytes, type);
122	    }
123	
124	    public static <T> T readValue(String string, TypeReference<T> type) throws IOException {
125	        return mapper.readValue(string, type);
126	    }
127	
128	    public static <T> T readValue(InputStream bytes, TypeReference<T> type) throws IOException {
129	        return mapper.readValue(bytes, type);
130	    }
131	
132	    /**
133	     * Creates an {@link ObjectNode} based on the given {@code pojo}, copying all its properties to the resulting {@link ObjectNode}.
134	     *
135	     * @param pojo a pojo which properties will be populates into the resulting a {@link ObjectNode}
136	     * @return a {@link ObjectNode} with all the properties from the given pojo
137	     * @throws IOException if the resulting a {@link ObjectNode} can not be created
138	     */
139	    public static ObjectNode createObjectNode(Object pojo) throws IOException {
140	        if (pojo == null) {
141	            throw new IllegalArgumentException("Pojo can not be null.");
142	        }
143	
144	        ObjectNode objectNode = createObjectNode();
145	        JsonNode jsonNode;
146	        try (JsonParser jsonParser = mapper.getFactory().createParser(writeValueAsBytes(pojo))) {
147	            jsonNode = jsonParser.readValueAsTree();
148	        }
149	
150	        if (!jsonNode.isObject()) {
151	            throw new RuntimeException("JsonNode [" + jsonNode + "] is not a object.");
152	        }
153	
154	        objectNode.setAll((ObjectNode) jsonNode);
155	
156	        return objectNode;
157	    }
158	
159	    public static ObjectNode createObjectNode() {
160	        return mapper.createObjectNode();
161	    }
162	
163	}
