62	    /**
63	     * <p> Perform a runtime cast. Similar to {@link Class#cast(Object)}, but useful when you do not have a {@link
64	     * Class} object for type you wish to cast to. </p> <p/> <p> {@link Class#cast(Object)} should be used if possible
65	     * </p>
66	     *
67	     * @param <T> the type to cast to
68	     * @param obj the object to perform the cast on
69	     *
70	     * @return the casted object
71	     *
72	     * @throws ClassCastException if the type T is not a subtype of the object
73	     * @see Class#cast(Object)
74	     */
75	    @SuppressWarnings("unchecked")
76	    public static <T> T cast(Object obj) {
77	        return (T) obj;
