80	    /**
81	     * Get all the declared fields on the class hierarchy. This <b>will</b> return overridden fields.
82	     *
83	     * @param clazz The class to search
84	     *
85	     * @return the set of all declared fields or an empty set if there are none
86	     */
87	    public static Set<Field> getAllDeclaredFields(Class<?> clazz) {
88	        HashSet<Field> fields = new HashSet<Field>();
89	        for (Class<?> c = clazz; c != null && c != Object.class; c = c.getSuperclass()) {
90	            for (Field a : c.getDeclaredFields()) {
91	                fields.add(a);
92	            }
93	        }
94	        return fields;
95	    }
