97	    /**
98	     * Search the class hierarchy for a field with the given name. Will return the nearest match, starting with the
99	     * class specified and searching up the hierarchy.
100	     *
101	     * @param clazz The class to search
102	     * @param name The name of the field to search for
103	     *
104	     * @return The field found, or null if no field is found
105	     */
106	    public static Field findDeclaredField(Class<?> clazz, String name) {
107	        for (Class<?> c = clazz; c != null && c != Object.class; c = c.getSuperclass()) {
108	            try {
109	                return c.getDeclaredField(name);
110	            } catch (NoSuchFieldException e) {
111	                // No-op, we continue looking up the class hierarchy
112	            }
113	        }
114	        return null;
115	    }
