117	    /**
118	     * Search for annotations with the specified meta annotation type
119	     *
120	     * @param annotations The annotation set to search
121	     * @param metaAnnotationType The type of the meta annotation to search for
122	     *
123	     * @return The set of annotations with the specified meta annotation, or an empty set if none are found
124	     */
125	    public static Set<Annotation> getAnnotationsWithMetaAnnotation(
126	            Set<Annotation> annotations, Class<? extends Annotation> metaAnnotationType) {
127	        Set<Annotation> set = new HashSet<Annotation>();
128	        for (Annotation annotation : annotations) {
129	            if (annotation.annotationType().isAnnotationPresent(metaAnnotationType)) {
130	                set.add(annotation);
131	            }
132	        }
133	        return set;
134	    }
