136	    /**
137	     * Determine if a method exists in a specified class hierarchy
138	     *
139	     * @param clazz The class to search
140	     * @param name The name of the method
141	     *
142	     * @return true if a method is found, otherwise false
143	     */
144	    public static boolean methodExists(Class<?> clazz, String name) {
145	        for (Class<?> c = clazz; c != null && c != Object.class; c = c.getSuperclass()) {
146	            for (Method m : c.getDeclaredMethods()) {
147	                if (m.getName().equals(name)) {
148	                    return true;
149	                }
150	            }
151	        }
152	        return false;
153	    }
