251	    /**
252	     * <p> Loads and initializes a class for the given name. </p> <p/> <p> If the Thread Context Class Loader is
253	     * available, it will be used, otherwise the classloader used to load {@link Reflections} will be used </p> <p/> <p>
254	     * It is also possible to specify additional classloaders to attempt to load the class with. If the first attempt
255	     * fails, then these additional loaders are tried in order. </p>
256	     *
257	     * @param name the name of the class to load
258	     * @param loaders additional classloaders to use to attempt to load the class
259	     *
260	     * @return the class object
261	     *
262	     * @throws ClassNotFoundException if the class cannot be found
263	     */
264	    public static <T> Class<T> classForName(String name, ClassLoader... loaders) throws ClassNotFoundException {
265	        try {
266	            if (Thread.currentThread().getContextClassLoader() != null) {
267	                return (Class<T>) Class.forName(name, true, Thread.currentThread().getContextClassLoader());
268	            } else {
269	                return (Class<T>) Class.forName(name);
270	            }
271	        } catch (ClassNotFoundException e) {
272	            for (ClassLoader l : loaders) {
273	                try {
274	                    return (Class<T>) Class.forName(name, true, l);
275	                } catch (ClassNotFoundException ex) {
276	
277	                }
278	            }
279	        }
280	        if (Thread.currentThread().getContextClassLoader() != null) {
