893	        if (type2 instanceof ParameterizedType) {
894	            ParameterizedType parameterizedType = (ParameterizedType) type2;
895	            if (parameterizedType.getRawType() instanceof Class<?>) {
896	                if (matches(rawType1, actualTypeArguments1, (Class<?>) parameterizedType.getRawType(),
897	                        parameterizedType.getActualTypeArguments())) {
898	                    return true;
