1016	    /**
1017	     * <p>Resolves the type of items for a {@link Field} declared as a {@link List}.
1018	     *
1019	     * <p>This method will first try to check the parametrized type of the field type. If none is defined, it will try to infer
1020	     * the type of items by looking at the value of the field for the given {@code instance}.
1021	     *
1022	     * <p>Make sure the field is accessible before invoking this method.
1023	     *
1024	     * @param field the field declared as {@link List}
1025	     * @param instance the instance that should be used to obtain infer the type in case no parametrized type is found in the field.
1026	     * @return if the field is not a {@link List}, it returns null. Otherwise the type of items of the list. If the type for items can not be inferred, the {@link Object} type is returned.
1027	     * @throws IllegalAccessException in case it fails to obtain the value of the field from the {@code instance}
1028	     */
1029	    public static Class<?> resolveListType(Field field, Object instance) throws IllegalAccessException {
1030	        if (!List.class.isAssignableFrom(field.getType())) {
1031	            return null;
1032	        }
1033	
1034	        Type genericType = field.getGenericType();
1035	
1036	        if (genericType instanceof ParameterizedType) {
1037	            Type[] typeArguments = ParameterizedType.class.cast(genericType)
1038	                    .getActualTypeArguments();
1039	
1040	            if (typeArguments[0] instanceof Class) {
1041	                return (Class<?>) typeArguments[0];
1042	            }
1043	        } else if (instance != null) {
1044	            // just in case the field is not parametrized
1045	            List item = List.class.cast(field.get(instance));
1046	
1047	            if (!item.isEmpty()) {
1048	                return item.get(0).getClass();
1049	            }
1050	        }
1051	
1052	        return Object.class;
1053	    }
