1055	    public static <T> T convertValueToType(Object value, Class<T> type) {
1056	
1057	        if (value == null) {
1058	            return null;
1059	
1060	        } else if (value instanceof String) {
1061	            if (type == String.class) {
1062	                return type.cast(value);
1063	            } else if (type == Boolean.class) {
1064	                return type.cast(Boolean.parseBoolean(value.toString()));
1065	            } else if (type == Integer.class) {
1066	                return type.cast(Integer.parseInt(value.toString()));
1067	            } else if (type == Long.class) {
1068	                return type.cast(Long.parseLong(value.toString()));
1069	            }
1070	        } else if (value instanceof Number) {
1071	            if (type == Integer.class) {
1072	                return type.cast(((Number) value).intValue());
1073	            } else if (type == Long.class) {
1074	                return type.cast(((Number) value).longValue());
1075	            } else if (type == String.class) {
1076	                return type.cast(value.toString());
1077	            }
1078	        } else if (value instanceof Boolean) {
1079	            if (type == Boolean.class) {
1080	                return type.cast(value);
1081	            } else if (type == String.class) {
1082	                return type.cast(value);
1083	            }
1084	        }
1085	
1086	        throw new RuntimeException("Unable to handle type [" + type + "]");
1087	    }
