154	    /**
155	     * See if the two methods are compatible, that is they have the same relative signature
156	     *
157	     * @param method
158	     * @param intfMethod
159	     * @return
160	     */
161	    public static boolean isCompatible(Method method, Method intfMethod)
162	    {
163	        if (method == intfMethod) return true;
164	
165	        if (!method.getName().equals(intfMethod.getName())) return false;
166	        if (method.getParameterCount() != intfMethod.getParameterCount()) return false;
167	
168	        for (int i = 0; i < method.getParameterCount(); i++)
169	        {
170	            Class rootParam = method.getParameterTypes()[i];
171	            Class intfParam = intfMethod.getParameterTypes()[i];
172	            if (!intfParam.isAssignableFrom(rootParam)) return false;
173	        }
174	        return true;
175	    }
