423	    /**
424	     * Finds an actual value of a type variable. The method looks in a class hierarchy for a class defining the variable
425	     * and returns the value if present.
426	     *
427	     * @param root
428	     * @param typeVariable
429	     * @return actual type of the type variable
430	     */
431	    public static Type resolveTypeVariable(Class<?> root, TypeVariable<?> typeVariable)
432	    {
433	        if (typeVariable.getGenericDeclaration() instanceof Class<?>)
434	        {
435	            Class<?> classDeclaringTypeVariable = (Class<?>) typeVariable.getGenericDeclaration();
436	            Type[] types = findParameterizedTypes(root, classDeclaringTypeVariable);
437	            if (types == null) return  null;
438	            for (int i = 0; i < types.length; i++)
439	            {
440	                TypeVariable<?> tv = classDeclaringTypeVariable.getTypeParameters()[i];
441	                if (tv.equals(typeVariable))
442	                {
443	                    return types[i];
444	                }
445	            }
446	        }
447	        return null;
448	    }
